            if (!waypoint) continue
            requireDiagramGridNumber(waypoint.x, `edges.new.waypoints[${index}].x`)
            requireDiagramGridNumber(waypoint.y, `edges.new.waypoints[${index}].y`)
            const previous = edge.waypoints?.[index - 1]
